#!/bin/bash
# 使用方法: ./extract_gbs_libs.sh <platform> <gbs_version>
# platform: linux-x86_64-gcc940、linux-aarch64-gcc940 或 linux-aarch64-gcc1330
# gbs_version: GBS版本分支名，如 GBS_1.14

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
GALBOT_SDK_COMMON_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
PLATFORM=$1
GBS_VERSION=$2

if [ -z "${PLATFORM}" ] || [ -z "${GBS_VERSION}" ]; then
    echo "错误: 缺少参数"
    echo "使用方法: $0 <platform> <gbs_version>"
    echo "  platform: linux-x86_64-gcc940、linux-aarch64-gcc940 或 linux-aarch64-gcc1330"
    echo "  gbs_version: GBS版本分支名，如 GBS_1.14"
    exit 1
fi

# 检查platform是否有效
if [ "${PLATFORM}" != "linux-x86_64-gcc940" ] && [ "${PLATFORM}" != "linux-aarch64-gcc940" ] && [ "${PLATFORM}" != "linux-aarch64-gcc1330" ]; then
    echo "错误: 不支持的平台 ${PLATFORM}"
    echo "支持的平台: linux-x86_64-gcc940, linux-aarch64-gcc940, linux-aarch64-gcc1330"
    exit 1
fi

# 确定架构类型映射和GBS提取目录名称
if [ "${PLATFORM}" == "linux-x86_64-gcc940" ]; then
    EXTRACT_TYPE_ARCH=3
    GBS_ARCH_DIR="gcc940-x86_64-ubuntu2004-gnu"
elif [ "${PLATFORM}" == "linux-aarch64-gcc940" ]; then
    EXTRACT_TYPE_ARCH=2
    GBS_ARCH_DIR="gcc940-aarch64-ubuntu2004-gnu"
elif [ "${PLATFORM}" == "linux-aarch64-gcc1330" ]; then
    EXTRACT_TYPE_ARCH=7
    GBS_ARCH_DIR="gcc13.3-aarch64-ubuntu2404-gnu"
fi
EXTRACT_TYPE_PB=5

# GBS submodule路径
GBS_SUBMODULE_DIR="${GALBOT_SDK_COMMON_DIR}/submodules/xcu_common_lib"

THIRDPARTY_TARGET_DIR="${GALBOT_SDK_COMMON_DIR}/submodules/ThirdParty/${GBS_ARCH_DIR}"
VERSION_MARKER_FILE="${THIRDPARTY_TARGET_DIR}/.gbs_version"

# 关键库文件列表（用于验证提取是否完整）
# 注意：库文件可能带版本号（如libprotobuf.so.3.14.0），所以检查时使用通配符
KEY_LIBRARIES=(
    "lib/libspdlog.so*"
    "lib/libprotobuf.so*"
    "include/spdlog/spdlog.h"
    "include/google/protobuf/message.h"
)

echo "=========================================="
echo "检查GBS三方库提取状态"
echo "=========================================="
echo "平台: ${PLATFORM}"
echo "GBS版本: ${GBS_VERSION}"

