template <typename ProtoTimestamp>
void set_proto_timestamp(ProtoTimestamp* proto_timestamp, int64_t sec, uint32_t nanosec) {
  if (proto_timestamp == nullptr) {
    return;
  }
  proto_timestamp->set_sec(sec);
  proto_timestamp->set_nanosec(nanosec);
}

template <typename ProtoTimestamp>
void set_proto_timestamp_from_ns(ProtoTimestamp* proto_timestamp, int64_t timestamp_ns) {
  if (proto_timestamp == nullptr) {
    return;
  }
  if (timestamp_ns < 0) {
    timestamp_ns = 0;
  }
  const int64_t sec = timestamp_ns / 1000000000LL;
  const uint32_t nanosec = static_cast<uint32_t>(timestamp_ns % 1000000000LL);
  set_proto_timestamp(proto_timestamp, sec, nanosec);
}

template <typename ProtoDuration>
void set_proto_duration_from_seconds(ProtoDuration* proto_duration, double time_from_start_s) {
  if (proto_duration == nullptr) {
    return;
  }
  double integral = 0.0;
  double fractional = std::modf(time_from_start_s, &integral);
  int64_t sec = static_cast<int64_t>(integral);
  auto nanosec = static_cast<uint32_t>(std::llround(fractional * 1e9));

