// 模拟 SDK 里的一个"接口头文件"(对比: submodules/galbot_robot/include/galbot_robot.hpp)
#pragma once

#include <string>

namespace greet {

// 一个简单的类,模拟 GalbotRobot 的结构:头文件声明 + cpp 实现
class Greeter {
 public:
  explicit Greeter(const std::string& name);
  std::string hello() const;
  // 模拟"版本号宏"(真实 SDK 用 CMake 注入 GALBOT_SDK_VERSION)
  static int version();

 private:
  std::string name_;
};

// 枚举,模拟 MachineType / ControlStatus 这类简单类型
enum class Mood { HAPPY, CALM, CURIOUS };

}  // namespace greet

// 模拟 SDK 模块的实现代码(对比: submodules/galbot_robot/src/galbot_robot.cpp)
#include "greet/greet.hpp"

namespace greet {

Greeter::Greeter(const std::string& name) : name_(name) {}

std::string Greeter::hello() const {
  return "hello, " + name_ + " (from C++ libgreet)";
}

int Greeter::version() { return 10000 + 10 * 10 + 0; }  // 假装 1.10.0

}  // namespace greet

// 模拟 SDK 各模块的 pybind 绑定(对比: submodules/galbot_robot/pybind/src/galbot_robot_pybind.cpp)
// 这里的 PYBIND11_MODULE(greeter, m) 对应真实 SDK 顶层
//   pybind/src/pybind_galbot.cpp 里的 PYBIND11_MODULE(galbot_sdk, m)
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

#include "greet/greet.hpp"

namespace py = pybind11;
using namespace greet;

PYBIND11_MODULE(greeter, m) {
  m.doc() = "mini demo: 模拟 galbot_sdk 的 pybind 模块";
  m.attr("__version__") = "1.10.0";

  py::enum_<Mood>(m, "Mood")
      .value("HAPPY", Mood::HAPPY)
      .value("CALM", Mood::CALM)
      .value("CURIOUS", Mood::CURIOUS);

  py::class_<Greeter>(m, "Greeter")
      .def(py::init<const std::string&>(), py::arg("name"))
      .def("hello", &Greeter::hello)
      .def_static("version", &Greeter::version);
}

