// C++ 侧使用 SDK 的最小示例
// 对应官方 examples/g1/cpp/ 里的写法:include 头文件 + 链接 libgalbot_sdk.so
//
// 注意:本程序只使用"纯数据结构"和枚举,不会调用 init(),
//      所以不需要连接机器人就能编译 + 运行,用来验证 SDK 链接是否正确。
#include <iostream>

#include "galbot_sdk/galbot_sdk_type.hpp"  // 来自 output/.../include/galbot_sdk/

int main() {
  std::cout << "== Galbot SDK C++ 链接验证 ==\n";

  // 枚举(编译期常量,展示 SDK 类型可用)
  galbot::sdk::MachineType m = galbot::sdk::MachineType::G1;
  std::cout << "MachineType::G1 = " << static_cast<int>(m) << "\n";

  // 纯数据结构(不涉及任何网络/机器人)
  galbot::sdk::Point2d p;
  p.x = 1.5;
  p.y = -2.0;
  galbot::sdk::Pose2d pose;
  pose.position = p;
  pose.theta = 0.785;

  std::cout << "Point2d(" << p.x << ", " << p.y << ")\n";
  std::cout << "Pose2d: x=" << pose.position.x << " y=" << pose.position.y
            << " theta=" << pose.theta << "\n";

  std::cout << "\n✅ C++ 程序成功包含并链接了 libgalbot_sdk.so\n";
  std::cout << "   (未调用 init(),因此无需机器人)\n";
  return 0;
}
